        for a, b in boundary:
            nxt.setdefault(a, []).append(b)
        loops = []
        used = set()
        for a, b in boundary:
            if (a, b) in used:
                continue
            loop = [a]
            cur, prev = b, a
            used.add((a, b))
            guard = 0
            while cur != a and guard < 100000:
                loop.append(cur)
                cands = [c for c in nxt.get(cur, []) if (cur, c) not in used]
                if not cands:
                    break
                c = cands[0]
                used.add((cur, c))
                prev, cur = cur, c
                guard += 1
            loops.append(loop)
        return loops

